const EXAM_DEFAULT = [{"src":"第76回 午後 第85問","q":"上部消化管造影写真（別冊No. 6）を別に示す。正しいのはどれか。","c":["腹臥位の画像である。","立位で撮影している。","噴門部が明瞭に描出されている。","胃体中部後壁の描出を目的としている。","胃角部の小弯線が U 字に描出されている。"],"a":[4],"e":"背臥位の二重造影像。余分なバリウムは背側の胃底部へ落ち、胃体部の後壁がガスで広げられて描出されている。","set":[0,0],"img":"data:image/jpeg;base64,","ann":[[80,11,"胃底部（バリウムが溜まる）"],[55,30,"椎体"],[70,40,"胃体部後壁（二重造影）"],[17,78,"大弯側の輪郭"]]},{"src":"第74回 午後 第93問","q":"上部消化管造影写真（別冊No. 15）を別に示す。撮影体位はどれか。","c":["背臥位第1斜位","背臥位第2斜位","半立位第1斜位","半立位第2斜位","立位第1斜位"],"a":[4],"e":"半立位第2斜位。台を起こして左側を挙上すると胃体上部から噴門部が開く。写真では胃小区が明瞭で付着が良好。","set":[45,315],"img":"data:image/jpeg;base64,","ann":[[42,20,"ガスで広がった胃上部"],[30,45,"胃小区（付着が良い）"],[26,84,"落ちたバリウム"],[54,94,"ここより下は画面外"]]},{"src":"第65回 午後 第81問","q":"上部消化管造影写真（別冊No. 3）を別に示す。正しいのはどれか。","c":["前壁が描出されている。","背臥位で撮影されている。","頭高位で撮影されている。","充盈法で撮影されている。","噴門部から穹窿部が描出されている。"],"a":[1],"e":"腹臥位の前壁二重造影像。腹側が低くなり前壁にバリウムが付着、ガスは背側の胃底部へ抜ける。","set":[0,180],"img":"data:image/jpeg;base64,","ann":[[25,50,"粘膜ヒダ"],[57,72,"バリウムの溜まり"]]},{"src":"第71回 午前 第89問","q":"胃噴門部に異常が疑われた場合の上部消化管 X 線二重造影で、適切な撮影はどれか。2つ選べ。","c":["右側臥位像","背臥位正面像","背臥位第1斜位像","背臥位第2斜位像","半立位第2斜位像"],"a":[1,5],"e":"噴門部は背臥位正面ではバリウムに浸る。右側臥位でバリウムを幽門側へ逃がすか、半立位第2斜位で噴門部を開いて二重造影にする。","set":[45,315]},{"src":"第72回 午前 第90問","q":"上部消化管造影の圧迫撮影で、観察が難しい部位はどれか。","c":["胃 角","噴門部","幽門部","胃体下部","十二指腸球部"],"a":[2],"e":"噴門部は深部にあり圧迫筒が届かない。圧迫撮影は前庭部・胃角部・十二指腸球部など浅い部位に有効。","set":[90,0]},{"src":"第78回 午後 第86問","q":"立位胸部 X 線写真と比較して、仰臥位ポータブル胸部 X 線写真の特徴で正しいのはどれか。","c":["胃泡が明瞭になる。","心陰影が縮小する。","肺尖部が広く描出される。","肺野への肩甲骨の重なりが減少する。","心陰影に重なる肺血管の描出が不良になる。"],"a":[5],"e":"立位では胃泡が横隔膜下に明瞭な鏡面をつくるが、仰臥位ではガスが腹側へ広がり不明瞭になる。臥位では肺血流が背側へ再分布する。","set":[0,0]},{"src":"第70回 午後 第88問","q":"急性腹症患者の左側臥位腹部正面撮影で正しいのはどれか。","c":["腹水貯留の診断に用いる。","尿管結石の診断に用いる。","消化管穿孔の診断に用いる。","発泡剤を飲ませてから撮影する。","ポジショニング後は素早く撮影する。"],"a":[3],"e":"左側臥位では遊離ガスが右側（肝臓の外側）に集まり、消化管穿孔による腹腔内遊離ガスを描出できる。ガスが移動しきるまで数分待つ。","set":[0,90]},{"src":"第78回 午前 第87問","q":"上部消化管造影検査で正しいのはどれか。","c":["窒素で胃を膨らませる。","二重造影では胃小区を描出する。","硫酸バリウムの使用量は 500 mL 程度である。","半立位第 2 斜位撮影では幽門部を描出できる。","Brown〈ブラウン〉法による前処置を実施する。"],"a":[2],"e":"胃小区は良好な二重造影でのみ描出される微細な粘膜模様。発泡剤が出すのは炭酸ガス、バリウムは150 mL程度、Brown法は注腸の前処置。","set":[0,0]},{"src":"第77回 午後 第88問","q":"胃部 X 線造影検査で正しいのはどれか。 2 つ選べ。","c":["検査後は飲水を制限する。","胃小区の描出は二重造影で行う。","炭酸ガスを使用して胃を膨らませる。","硫酸バリウムの使用量は 500 mL 程度である。","Brown〈ブラウン〉法による前処置を実施する。"],"a":[2,3],"e":"発泡剤が胃内で炭酸ガスを発生させ、陰性造影剤として胃を拡張する。検査後はむしろ水分と下剤でバリウムを排出させる。","set":[0,0]},{"src":"第75回 午前 第91問","q":"胃部 X 線造影検査で誤っているのはどれか。","c":["圧迫撮影法では凹凸病変の形態が観察できる。","二重造影法では陰性造影剤として炭酸ガスを使用する。","注腸造影検査に比べて低濃度の硫酸バリウムを使用する。","胃粘膜面に硫酸バリウムを付着させる目的で体位変換を行う。","背臥位二重造影第 1 斜位像では十二指腸球部から前庭部が描出される。"],"a":[3],"e":"胃は注腸より高濃度のバリウムを少量使う。粘膜への付着を良くするためで、注腸は低濃度・大量。","set":[0,45]},{"src":"第70回 午後 第89問","q":"胃部 X 線造影検査で正しいのはどれか。","c":["窒素で胃を膨らませる。","二重造影では胃小区を描出する。","硫酸バリウムの使用量は 500 mL 程度である。","半立位第2斜位撮影では幽門部を描出できる。","Brown〈ブラウン〉法による前処置を実施する。"],"a":[2],"e":"第78回午前第87問と同じ設問。胃小区の描出は付着が良好な二重造影でのみ得られる。","set":[0,0]},{"src":"第71回 午前 第58問","q":"胃において十二指腸に連続する部位はどれか。","c":["噴 門","幽 門","胃角部","胃体部","胃底部"],"a":[2],"e":"幽門。噴門は食道との接続部。右側臥位にすると幽門が低くなり造影剤が十二指腸球部へ流入する。","set":[0,270]},{"src":"第67回 午前 第54問","q":"ガストリンを分泌する細胞が主に存在するのはどれか。","c":["噴門部","胃底部","胃体部","胃角部","幽門部"],"a":[5],"e":"ガストリンは幽門前庭部のG細胞から分泌され、胃酸分泌を促す。","set":[0,270]},{"src":"第73回 午前 第83問","q":"胃角に異常が疑われた場合の上部消化管造影検査における撮影体位で、最も適切なのはどれか。","c":["右側臥位像","背臥位正面像","再立位第1斜位像","背臥位第1斜位像","半立位第2斜位像"],"a":[2],"e":"背臥位正面の二重造影では、胃角部の小弯線が重なりなく描出される。","set":[0,0]}];   // 体位を再現できる問題だけ（解剖・生理・造影剤の計算などの 8 問は 2026-10-28 に外した）
